CREATE TABLE product_option_group(id BIGINT NOT NULL AUTO_INCREMENT,product_id BIGINT NOT NULL,group_name VARCHAR(100) NOT NULL,selection_type VARCHAR(20) NOT NULL,required_option BIT NOT NULL,min_selection INT NOT NULL,max_selection INT NOT NULL,sort_order INT NOT NULL,exposed BIT NOT NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,PRIMARY KEY(id));
CREATE TABLE product_option_value(id BIGINT NOT NULL AUTO_INCREMENT,option_group_id BIGINT NOT NULL,value_name VARCHAR(100) NOT NULL,additional_price DECIMAL(19,2) NOT NULL,inventory_managed BIT NOT NULL,stock_quantity INT NOT NULL,sale_status VARCHAR(30) NOT NULL,sort_order INT NOT NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,PRIMARY KEY(id));
CREATE TABLE product_addon_group(id BIGINT NOT NULL AUTO_INCREMENT,product_id BIGINT NOT NULL,group_name VARCHAR(100) NOT NULL,min_quantity INT NOT NULL,max_quantity INT NOT NULL,sort_order INT NOT NULL,exposed BIT NOT NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,PRIMARY KEY(id));
CREATE TABLE product_addon_item(id BIGINT NOT NULL AUTO_INCREMENT,addon_group_id BIGINT NOT NULL,addon_product_id BIGINT NOT NULL,max_quantity INT NOT NULL,sort_order INT NOT NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,PRIMARY KEY(id),CONSTRAINT uk_addon_group_product UNIQUE(addon_group_id,addon_product_id));
CREATE INDEX idx_option_group_product ON product_option_group(product_id);CREATE INDEX idx_option_value_group ON product_option_value(option_group_id);CREATE INDEX idx_addon_group_product ON product_addon_group(product_id);CREATE INDEX idx_addon_item_group ON product_addon_item(addon_group_id);
